/// <summary>
/// Base class for the logic blocks used to encapsulate Data collection and posting logic
/// </summary>
class TFMLogicBlock
{
    TFMReferenceDataConfiguration       refConf;
    TFMLogicComponentCollection         components;
    Name                                name;
    TFMLogicInputOutputContainer        outputs, inputs;
    TFMLogicBlockDataInheritanceHandler inheritanceHandler;
    TFMRequestElement                   request;
    TFMLogicContext                     logicContext;
    Map                                 fields;
    Set                                 categories;
    int                                 instanceId;

}

Method.Source:
public void setInstanceID(int _instanceID)
{
    instanceId = _instanceID;
}

public int getInstanceID()
{
    return instanceId ? instanceId : this.GetHashCode();
}

public TFMLogicInputOutputContainer inputs()
{
    return inputs;
}

/// <summary>
/// This method can be implemented, if the block should deliver its own process instance, and thereby bypass the need to create a class for that purpose
/// </summary>
/// <returns>A TFMProcess object, if block should provide its own process.</returns>
public Set autoCreatedProcesses()
{
    return new Set(Types::Class);
}

public TFMLogicInputOutputContainer outputs()
{
    return outputs;
}

public TFMRequestElement parmRequest(TFMRequestElement _request = request)
{

    if (!request && _request)
    {
        components.setRequests(_request);
    }
    request = _request;
    return request;
}

public TFMLogicContext parmLogicContext(TFMLogicContext _logicContext = logicContext)
{
    logicContext = _logicContext;
    return logicContext;
}

public void addField(str _key, str _value)
{
    fields.insert(_key,_value);
}

public str getFieldValue(str _key)
{
    return fields.exists(_key) ? fields.lookup(_key) : '';
}

public Map parmFieldMap(Map _fields = fields)
{
    fields = _fields;
    return fields;
}

public void new()
{
    this.fillInParms();
    refConf = new TFMReferenceDataConfiguration();
    components = TFMLogicComponentCollection::Construct();  
    outputs = TFMLogicInputOutputContainer::Construct();        
    outputs.addConnectionName('output_1');
    inputs  = TFMLogicInputOutputContainer::Construct();
    inputs.addConnectionName('input_1');
    inheritanceHandler  = TFMLogicBlockDataInheritanceHandler::Construct();
    fields = new Map(Types::String, Types::String);
    categories = new Set(Types::String);

    // if the LogicBlock implements step operator then add the category
    if(this is TFMLogicStepOperatorInterface)
    {
        categories.add("@TFM:Logic");
    }
}

public TFMLogicBlockDataInheritanceHandler inheritedValues()
{
    return inheritanceHandler;
}

public void setInheritance(TFMLogicBlockDataInheritanceHandler _inheritance)
{
    inheritanceHandler = _inheritance;
}

public void fillInParms()
{
    //Fill all parm methods
    SetEnumerator methods = TFMFormLookupHelper::parmMethodsOnClass(classIdGet(this),false,Types::Class).getEnumerator();
    int								j;
    DictMethod						DM;
    TFMParameterAttribute			parmAttr;
    Array							array;
    while (methods.moveNext())
    {
        DM = methods.current();
        array = DM.getAttributes(classstr(TFMParameterAttribute));
        if (array != null)
        {
            for (j = 1; j <= array.lastIndex(); j++)
            {
                parmAttr = array.value(j);
                new SysDictClass(classIdGet(this)).callObject(DM.name(),this,parmAttr.parmDefaultValue());
            }
        }
    }
}

public void initBlock(TFMProcess _process)
{
    //if(_process.parmVersion() < 0)
    //{
    //    return; // no need to init when no version. It is probably a process template.
    //}

    //Init parm methods from block as well as components
    TFMLogicComponent               component;
    //Find subcomponents parameters
    MapEnumerator   componentsEnum = components.componentSet().getEnumerator();
    str             domainKey = TFMProcessBlocksParametersEdit::GetProcessContentForGenericParmsForBlocks(_process, name);
    this.updateInstance(this,domainKey, classId2Name(classIdGet(this)));
    while (componentsEnum.moveNext())
    {
        component = componentsEnum.currentValue();
        this.updateInstance(component, domainKey, classId2Name(classIdGet(this)));
        //edt.populateGroupWithDocParms(classIdGet(component),fgc);
    }

}

protected void updateInstance(Object _instance, str _domain, ClassName _className)
{
    ClassId                 instanceClassId = classIdGet(_instance);
    Set					    methodsOnClass  = TFMFormLookupHelper::parmMethodsOnClass(instanceClassId,false,Types::Class);
    SetEnumerator		    sEnum = methodsOnClass.getEnumerator();
    SysDictMethod		    dm;
    TFMParameterAttribute   parmAttr;
    anytype                 retVal;
    Array                   array;
    int                     j;
    SysDictClass instanceSysDicClass = new SysDictClass(instanceClassId);

    while (sEnum.moveNext())
    {
        //step Through all Parm methods, turn to attributes
        dm = sEnum.current();
        if (TFMGenericParms::Exists(_domain,_className, dm.name()))
        {
            //Update Parameter from Override
            instanceSysDicClass.callObject(dm.name(),_instance, TFMGenericParms::getValue(_domain, _className,dm.name()));
        }
        /*else
        {
            //Initiate standard value
            array = dm.getAttributes(classstr(TFMParameterAttribute));
            if (array != null)
            {
                for (j = 1; j <= array.lastIndex(); j++)
                {
                    parmAttr = array.value(j);

                    new SysDictClass(classIdGet(_instance)).callObject(dm.name(),_instance, parmAttr.parmDefaultValue());
                }
            }
        }*/
    }
}

/// <summary>
/// Get or set the name of the block within the process/block Collection.
/// </summary>
/// <param name = "_name">Name to give the block</param>
/// <returns>Name of the block</returns>
public Name parmName(Name _name = name)
{
    name = _name;
    return name;
}

public Set parmCategories(Set _categories = categories)
{
    categories = _categories;
    return categories;
}

public TFMLogicComponentCollection components()
{
    return components;
}

/// <summary>
/// Name of the block Type. Override this method if you want to give the block a translated label, instead of the generated for the Class name.
/// </summary>
/// <returns>Name of the block</returns>
public Name blockName()
{
    return TFMHelper::convertCamelCaseToNiceText(subStr(classId2Name(classIdGet(this)),strLen(classStr(TFMLogicBlock))+1,100));
}

public str blockIcon()
{
    return resourceStr(TFMBlockSettings);
}

public TFMRequestElement modifyRequest(TFMRequestElement _request)
{
    return components.modifyRequest(_request);
}
